import numpy as np
import time


def _R(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = np.convolve(h, h)
    L = np.concatenate(([0.0], L, [0.0]))
    num = np.sum(L[:-1] ** 2 + L[:-1] * L[1:] + L[1:] ** 2) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _make(N, s1, s2, w):
    c = (N - 1) / 2.0
    i = np.arange(N, dtype=float)
    return (np.exp(-0.5 * ((i - c) / s1) ** 2)
            + w * np.exp(-0.5 * ((i - c) / s2) ** 2))


def construct(budget_seconds, start):
    t0 = time.process_time()
    N = 8001
    best = None
    best_R = -1.0

    s1s = [200.0, 400.0, 800.0]
    s2s = [800.0, 1600.0, 3200.0, 6400.0]
    ws = [0.1, 0.3, 1.0, 3.0]

    for s1 in s1s:
        for s2 in s2s:
            if time.process_time() - t0 > budget_seconds * 0.5:
                break
            for w in ws:
                h = _make(N, s1, s2, w)
                r = _R(h)
                if r > best_R:
                    best_R = r
                    best = (s1, s2, w)

    # coordinate descent refinement
    if best is not None:
        s1, s2, w = best
        steps = [0.5, 0.25, 0.125]
        for _ in range(3):
            improved = True
            while improved:
                if time.process_time() - t0 > budget_seconds * 0.85:
                    break
                improved = False
                for ds1 in (-steps[0] * s1, steps[0] * s1):
                    ns1 = max(10.0, s1 + ds1)
                    r = _R(_make(N, ns1, s2, w))
                    if r > best_R:
                        best_R = r; s1 = ns1; improved = True
                for ds2 in (-steps[0] * s2, steps[0] * s2):
                    ns2 = max(10.0, s2 + ds2)
                    r = _R(_make(N, s1, ns2, w))
                    if r > best_R:
                        best_R = r; s2 = ns2; improved = True
                for dw in (-steps[0] * w, steps[0] * w):
                    nw = max(0.0, w + dw)
                    r = _R(_make(N, s1, s2, nw))
                    if r > best_R:
                        best_R = r; w = nw; improved = True
            steps = [s * 0.5 for s in steps]

    # resample best to N=20001
    Nout = 20001
    if best is None:
        h = np.ones(Nout)
    else:
        s1, s2, w = best
        h = _make(Nout, s1, s2, w)
    return h
